// ============================================================================
// USB4_apb: APB4 register wrapper around USB4_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/USB4.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/USB4.md
// ============================================================================
module USB4_apb #(
  parameter int MAXL = 32,
  parameter int RXB = 2,
  parameter int DELTA = 4,
  parameter int REFRESH = 128
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [7:0] tx_sym,
  input logic [7:0] rx_sym
);
  localparam logic [31:0] ID_VALUE = 32'h55340200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [10:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd11) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_link_up;
  logic [1:0]    c_path_en;
  logic [10:0]   c_hop_tx0;
  logic [10:0]   c_hop_tx1;
  logic [10:0]   c_hop_rx0;
  logic [10:0]   c_hop_rx1;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic [7:0]    c_tx_data;
  logic          c_tx_last;
  logic          c_tx_path;
  logic          c_rx_valid;
  logic          c_rx_ready;
  logic [7:0]    c_rx_data;
  logic          c_rx_last;
  logic          c_rx_path;
  logic          c_sync;
  logic [1:0]    c_path_up;
  logic          c_ev_hec_fix;
  logic          c_ev_hec_bad;
  logic          c_ev_proto;
  logic          c_ev_hop;
  logic          c_ev_len;
  logic          c_ev_overflow;
  USB4_top #(.MAXL(MAXL), .RXB(RXB), .DELTA(DELTA), .REFRESH(REFRESH)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .link_up(c_link_up),
    .tx_sym(tx_sym),
    .rx_sym(rx_sym),
    .path_en(c_path_en),
    .hop_tx0(c_hop_tx0),
    .hop_tx1(c_hop_tx1),
    .hop_rx0(c_hop_rx0),
    .hop_rx1(c_hop_rx1),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_data(c_tx_data),
    .tx_last(c_tx_last),
    .tx_path(c_tx_path),
    .rx_valid(c_rx_valid),
    .rx_ready(c_rx_ready),
    .rx_data(c_rx_data),
    .rx_last(c_rx_last),
    .rx_path(c_rx_path),
    .sync(c_sync),
    .path_up(c_path_up),
    .ev_hec_fix(c_ev_hec_fix),
    .ev_hec_bad(c_ev_hec_bad),
    .ev_proto(c_ev_proto),
    .ev_hop(c_ev_hop),
    .ev_len(c_ev_len),
    .ev_overflow(c_ev_overflow)
  );

  // ---------------- registers ----------------
  logic [8:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [2:0] r_CTRL;   // 12'h014 CTRL
  logic [21:0] r_HOP0;   // 12'h018 HOP0
  logic [21:0] r_HOP1;   // 12'h01C HOP1
  logic [9:0] h_TX;   // 12'h020 TX holding register
  logic [9:0] h_RX;   // 12'h024 RX holding register
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 3'h0;
      r_HOP0 <= 22'h0;
      r_HOP1 <= 22'h0;
      h_TX <= '0;
      h_RX <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[8:0] & wmask[8:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[8:0]) | (PWDATA[8:0] & wmask[8:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[6]) r_HOP0 <= (r_HOP0 & ~wmask[21:0]) | (PWDATA[21:0] & wmask[21:0]);
      if (wr && hit[7]) r_HOP1 <= (r_HOP1 & ~wmask[21:0]) | (PWDATA[21:0] & wmask[21:0]);
      if (wr && hit[8] && !full_TX) h_TX <= (h_TX & ~wmask[9:0]) | (PWDATA[9:0] & wmask[9:0]);
      if (wr && hit[8] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[9]))) begin
        h_RX[7:0] <= c_rx_data[7:0];
        h_RX[8:8] <= c_rx_last;
        h_RX[9:9] <= c_rx_path;
        avail_RX <= 1'b1;
      end else if (rd && hit[9]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_link_up = r_CTRL[0:0];
  assign c_path_en = r_CTRL[2:1];
  assign c_hop_tx0 = r_HOP0[10:0];
  assign c_hop_rx0 = r_HOP0[21:11];
  assign c_hop_tx1 = r_HOP1[10:0];
  assign c_hop_rx1 = r_HOP1[21:11];
  assign c_tx_data[7:0] = h_TX[7:0];
  assign c_tx_last = h_TX[8:8];
  assign c_tx_path = h_TX[9:9];
  assign c_tx_valid = full_TX;
  assign c_rx_ready = ~avail_RX | (rd & hit[9]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_ev_hec_fix;
    irq_set[1] = c_ev_hec_bad;
    irq_set[2] = c_ev_proto;
    irq_set[3] = c_ev_hop;
    irq_set[4] = c_ev_len;
    irq_set[5] = c_ev_overflow;
    irq_set[6] = full_TX & c_tx_ready;
    irq_set[7] = wr & (hit[8]) & full_TX;
    irq_set[8] = c_rx_valid & (~avail_RX | (rd & hit[9]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_HOP0);
      10'd7: apb_rdata = 32'(r_HOP1);
      10'd8: apb_rdata = 32'(h_TX);
      10'd9: apb_rdata = 32'(h_RX);
      10'd10: apb_rdata = 32'({c_path_up, c_sync});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
